package com.yuegang.zhihui.order.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.order.application.*;import com.yuegang.zhihui.order.security.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/orders")public final class CommerceReconciliationController{private final CommerceReconciliationService service;private final OrderUserResolver users;public CommerceReconciliationController(CommerceReconciliationService s,OrderUserResolver u){service=s;users=u;}@PostMapping("/reconciliation")ApiResponse<CommerceReconciliationView>run(HttpServletRequest r){users.requirePermission(r,"order:reconcile");return ApiResponse.success(service.run(),TraceIdResolver.resolve(r));}}
